    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap: int = 0
    let mut first = true
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0].clone()
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut i = 0
            while i < keys.len() {
                if keys[i] == k {
                    keys.remove(i)
                    vals.remove(i)
                    break
                }
                i += 1
            }
            keys.insert(0, k)
            vals.insert(0, v)
            if (keys.len() as int) > cap {
                let last = keys.len() - 1
                println("evict {}", keys[last])
                keys.remove(last)
                vals.remove(last)
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found = false
            let mut i = 0
            while i < keys.len() {
                if keys[i] == k {
                    let v = vals[i]
                    keys.remove(i)
                    vals.remove(i)
                    keys.insert(0, k)
                    vals.insert(0, v)
                    println("{}", v)
                    found = true
                    break
                }
                i += 1
            }
            if !found {
                println("-1")
            }
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut s = ""
                let mut i = 0
                while i < keys.len() {
                    if i > 0 {
                        s = s + " "
                    }
                    s = s + keys[i].to_string()
                    i += 1
                }
                println("{}", s)
            }
        }
    }
}

